parameters.jsCode:
// KPI Snapshot v2 : dataset = série temporelle d'un seul UE
// -> rejeu par fenêtres de temps + détection d'anomalies par rapport à l'historique
const WINDOW = 60;              // nombre de mesures par exécution
const SLOT_MINUTES = 15;        // doit correspondre au Schedule Trigger
const Z_THRESHOLD = 3;

const COLS = {
  prb_dl: 'RRU.PrbTotDl', prb_ul: 'RRU.PrbTotUl',
  thp_dl: 'DRB.UEThpDl', thp_ul: 'DRB.UEThpUl',
  rlc_delay_dl: 'DRB.RlcSduDelayDl',
  vol_dl: 'DRB.PdcpSduVolumeDL', vol_ul: 'DRB.PdcpSduVolumeUL',
};
const num = v => { const n = Number(v); return Number.isFinite(n) ? n : null; };
const r2 = x => Number((x ?? 0).toFixed(2));
const mean = a => a.length ? a.reduce((s, x) => s + x, 0) / a.length : 0;
const std = a => { const m = mean(a); return Math.sqrt(mean(a.map(x => (x - m) ** 2))) || 1; };

// 1. Trier par temps (colonne Latency = timestamp en microsecondes)
const rows = $input.all().map(i => i.json)
  .filter(r => num(r['Latency']) !== null)
  .sort((a, b) => num(a['Latency']) - num(b['Latency']));
const toIso = us => new Date(Math.floor(us / 1000)).toISOString();

// 2. Référence historique (tout le dataset) : moyenne, écart-type, capacité PRB observée
const base = {};
for (const [k, c] of Object.entries(COLS)) {
  const v = rows.map(r => num(r[c])).filter(x => x !== null);
  base[k] = { mean: mean(v), std: std(v), max: Math.max(...v) };
}

// 3. Fenêtre courante : avance d'une fenêtre tous les SLOT_MINUTES (rejoue le dataset en boucle)
const nWindows = Math.max(1, Math.floor(rows.length / WINDOW));
const windowIndex = Math.floor(Date.now() / (SLOT_MINUTES * 60 * 1000)) % nWindows;
const win = rows.slice(windowIndex * WINDOW, windowIndex * WINDOW + WINDOW);

// 4. KPI de la fenêtre
const wavg = k => mean(win.map(r => num(r[COLS[k]])).filter(x => x !== null));
const raw = {};
for (const k of Object.keys(COLS)) raw[k] = wavg(k);

// RRU.PrbTotDl/Ul ne sont PAS des % : on normalise par la capacité max observée
const prbDlUtil = 100 * raw.prb_dl / (base.prb_dl.max || 1);
const prbUlUtil = 100 * raw.prb_ul / (base.prb_ul.max || 1);

// 5. Anomalies : mesures de la fenêtre à plus de Z_THRESHOLD écarts-types de l'historique
const anomalies = [];
for (const r of win) {
  for (const [k, c] of Object.entries(COLS)) {
    const v = num(r[c]); if (v === null) continue;
    const z = (v - base[k].mean) / base[k].std;
    if (Math.abs(z) >= Z_THRESHOLD) anomalies.push({ time: toIso(num(r['Latency'])), kpi: k, value: r2(v), z_score: r2(z) });
  }
}
anomalies.sort((a, b) => Math.abs(b.z_score) - Math.abs(a.z_score));

// 6. Règles réseau
const alerts = [];
// seuils relatifs à l'historique (les valeurs PRB brutes n'ont pas d'échelle fixe)
if (raw.prb_dl > base.prb_dl.mean + 2 * base.prb_dl.std) alerts.push('DL PRB usage above normal');
if (raw.prb_ul > base.prb_ul.mean + 2 * base.prb_ul.std) alerts.push('UL PRB usage above normal');
if (raw.rlc_delay_dl > base.rlc_delay_dl.mean + 2 * base.rlc_delay_dl.std) alerts.push('RLC DL delay above normal');
if (raw.thp_dl < base.thp_dl.mean - 2 * base.thp_dl.std) alerts.push('DL throughput below normal');

const status = alerts.length && anomalies.length ? 'ANOMALY'
  : alerts.length || anomalies.length ? 'WARNING' : 'NORMAL';

return [{ json: {
  timestamp: new Date().toISOString(),
  data_window: {
    index: windowIndex, of: nWindows, samples: win.length,
    start: win.length ? toIso(num(win[0]['Latency'])) : null,
    end: win.length ? toIso(num(win[win.length - 1]['Latency'])) : null,
  },
  status,
  measurements_analyzed: win.length,
  unique_ues: new Set(rows.map(r => r['UE.Id'])).size,
  network_kpis: {
    prb_dl: r2(prbDlUtil),            // % d'utilisation -> utilisé par le Digital Twin
    prb_ul: r2(prbUlUtil),
    prb_dl_raw: r2(raw.prb_dl), prb_ul_raw: r2(raw.prb_ul),
    thp_dl: r2(raw.thp_dl), thp_ul: r2(raw.thp_ul),
    rlc_delay_dl: r2(raw.rlc_delay_dl),
    max_rlc_delay_dl: r2(Math.max(0, ...win.map(r => num(r[COLS.rlc_delay_dl]) ?? 0))),
    vol_dl: r2(raw.vol_dl), vol_ul: r2(raw.vol_ul),
  },
  baseline: Object.fromEntries(Object.entries(base).map(([k, b]) => [k, { mean: r2(b.mean), std: r2(b.std), max: r2(b.max) }])),
  alerts,
  anomalous_ues_count: anomalies.length,   // (nom gardé pour Telegram / Prepare Log) = mesures anormales
  top_anomalies: anomalies.slice(0, 5),
} }];

const snapshot = $input.first().json;

return [{
  json: {
    ...snapshot,
    ai_analysis: {
      severity: 'LOW',
      diagnosis: 'Aucune anomalie réseau détectée par les règles déterministes.',
      recommendation: 'Continuer la surveillance du réseau.',
      requires_human_approval: false
    }
  }
}];

