parameters.jsCode:
const q = typeof query === 'string' ? JSON.parse(query) : query;

const missing = ['prb_dl', 'rlc_delay_dl', 'thp_dl'].filter(k => !Number.isFinite(Number(q[k])) || q[k] === null || q[k] === undefined);
if (missing.length) {
  return JSON.stringify({
    error: `Paramètres manquants : ${missing.join(', ')}. Rappelle l'outil en fournissant prb_dl, rlc_delay_dl et thp_dl copiés depuis network_kpis.`
  });
}

const PRB_MAX = 100;
const RHO_CAP = 0.98;

const prb = Number(q.prb_dl);
const delay = Number(q.rlc_delay_dl);
const thp = Number(q.thp_dl);
const traffic = Number(q.traffic_factor) || 1;
const capacity = Number(q.capacity_factor) || 1;

const rho = Math.min(prb / PRB_MAX, RHO_CAP);
const rhoRaw = (prb / PRB_MAX) * traffic / capacity;
const rhoNew = Math.min(rhoRaw, RHO_CAP);
const r2 = x => Number(x.toFixed(2));

const predictedDelay = delay * (1 - rho) / Math.max(0.01, 1 - rhoNew);
const predictedThp = thp * capacity * (1 - rhoNew) / Math.max(0.01, 1 - rho);

let risk = 'LOW';
if (rhoRaw >= 1) risk = 'CRITICAL';
else if (rhoRaw >= 0.9 || predictedDelay >= 50) risk = 'HIGH';
else if (rhoRaw >= 0.75 || predictedDelay >= 30) risk = 'MEDIUM';

return JSON.stringify({
  scenario: `traffic x${traffic}, capacity x${capacity}`,
  predicted_prb_dl: r2(Math.min(100, rhoRaw * 100)),
  predicted_rlc_delay_dl: r2(predictedDelay),
  predicted_thp_dl: r2(predictedThp),
  overloaded: rhoRaw >= 1,
  risk
});

