    "rlc_delay_dl": { "type": "number", "description": "Délai RLC DL actuel, = network_kpis.rlc_delay_dl" },
    "thp_dl": { "type": "number", "description": "Débit DL actuel, = network_kpis.thp_dl" },
    "traffic_factor": { "type": "number", "description": "Multiplicateur de trafic, ex: 1.2 pour +20%" },
    "capacity_factor": { "type": "number", "description": "Multiplicateur de capacité PRB, ex: 0.85 pour -15%" }
  },
  "required": ["traffic_factor", "capacity_factor"]
}

